def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                points.setdefault(grid[r][c], []).append((r, c))

    for color, pts in points.items():
        if len(pts) >= 2:
            # Join the upper/left point to the lower/right point with an elbow.
            a = min(pts, key=lambda p: (p[0], p[1]))
            b = max(pts, key=lambda p: (p[0], p[1]))
            r1, c1 = a
            r2, c2 = b
            for r in range(min(r1, r2), max(r1, r2) + 1):
                out[r][c1] = color
            for c in range(min(c1, c2), max(c1, c2) + 1):
                out[r2][c] = color
        else:
            r, c = pts[0]
            if r == 0 or r == h - 1:
                for rr in range(h):
                    out[rr][c] = color
            else:
                for cc in range(w):
                    out[r][cc] = color

    return out
